 94→    /// <summary>
 95→    /// 修改任务设置可见性, 用于 TaskQueueItem 设置按钮的切换.
 96→    /// </summary>
 97→    /// <param name="taskIndex">index</param>
 98→    /// <param name="enable">启用与否</param>
 99→    public void Set(int taskIndex, bool enable)
100→    {
101→        if (Guide && enable)
102→        {
103→            enable = false;
104→        }
105→
106→        // 边界检查
107→        if (taskIndex < 0 || taskIndex >= ConfigFactory.CurrentConfig.TaskQueue.Count)
108→        {
109→            Log.Error("尝试设置不存在的任务设置可见性, 索引: {TaskIndex}", taskIndex);
110→            return;
111→        }
112→
113→        var task = ConfigFactory.CurrentConfig.TaskQueue[taskIndex];
114→        if (enable)
115→        {
116→            CurrentIndex = taskIndex;
117→            SetTaskSettingVisible(task, enable);
118→        }
119→        else if (CurrentIndex == taskIndex)
120→        {
121→            CurrentIndex = -1;
122→            SetTaskSettingVisible(task, enable);
123→        }
124→
125→        if (enable)
126→        {
127→            Instances.TaskQueueViewModel.RefreshTaskModel(task);
128→        }
129→    }
