131→    public void SetTaskSettingVisible(BaseTask task, bool enable)
132→    {
133→        if (enable)
134→        {
135→            ResetVisible();
136→        }
137→        _ = task switch {
138→            StartUpTask => StartUp = enable,
139→            RecruitTask => Recruit = enable,
140→            InfrastTask => Infrast = enable,
141→            FightTask => Fight = enable,
142→            MallTask => Mall = enable,
143→            AwardTask => Award = enable,
144→            RoguelikeTask => Roguelike = enable,
145→            ReclamationTask => Reclamation = enable,
146→            CustomTask => Custom = enable,
147→            _ => throw new NotImplementedException(),
148→        };
149→        EnableAdvancedSettings = false;
150→        AdvancedSettingsVisibility = !Award && !StartUp;
151→    }
