154→    {
155→        StartUp = false;
156→        Recruit = false;
157→        Infrast = false;
158→        Fight = false;
159→        Mall = false;
160→        Award = false;
161→        Roguelike = false;
162→        Reclamation = false;
163→        Custom = false;
164→    }
